54	
55	    /**
56	     * Build the owner's canonical self link: '/api/owners/' followed by the owner's id. Returns null
57	     * when the owner has no id so an unsaved owner serializes cleanly.
58	     */
59	    default String selfLink(Owner owner) {
60	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
61	    }
62	
63	    /**
64	     * Build the owner's salutation: the honorific title followed by a single space and the last name
65	     * (e.g. 'DR Who') when a title is present, or just the last name when no title was supplied. A
66	     * blank title is treated as absent.
67	     */
68	    default String salutation(Owner owner) {
69	        String lastName = owner.getLastName();
70	        String title = owner.getTitle();
71	        if (title == null || title.trim().isEmpty()) {
72	            return lastName;
73	        }
74	        return title + " " + lastName;
75	    }
76	
77	    /**
78	     * Derive the owner's age band from the supplied birthDate, evaluated against the owner's
79	     * registrationDate: 'MINOR' when under 18, 'ADULT' when 18 to 64 inclusive, and 'SENIOR' when
80	     * 65 or older. Returns null when no birthDate was supplied (or no registrationDate is available)
81	     * so owners without a birth date serialize cleanly.
82	     */
83	    default String ageBand(Owner owner) {
84	        java.time.LocalDate birthDate = owner.getBirthDate();
85	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
86	        if (birthDate == null || registrationDate == null) {
87	            return null;
88	        }
89	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
90	        if (age < 18) {
91	            return "MINOR";
92	        }
93	        if (age < 65) {
94	            return "ADULT";
95	        }
96	        return "SENIOR";
97	    }
98	
99	    /**
100	     * The E.164 country calling codes whose split from the national number is recognised when
101	     * formatting {@code telephoneDisplay} (matching the codes validated on create). The longest
102	     * matching code wins so a shorter code that is a prefix of another cannot mask it.
103	     */
104	    java.util.Set<String> KNOWN_COUNTRY_CODES = java.util.Set.of("1", "61");
105	
106	    /**
107	     * Format the stored E.164 telephone for humans: the '+' and country calling code, a space, then
108	     * the national digits grouped in threes (e.g. '+61412345678' -&gt; '+61 412 345 678'). The
109	     * country code is split off using the recognised calling codes; when none matches, a single-digit
110	     * code is assumed so the value is still rendered as '+&lt;code&gt; &lt;grouped national&gt;'.
111	     * Returns the stored value unchanged when it is null or not in E.164 form.
112	     */
113	    default String telephoneDisplay(Owner owner) {
114	        String telephone = owner.getTelephone();
115	        if (telephone == null || !telephone.startsWith("+")) {
116	            return telephone;
117	        }
118	        String digits = telephone.substring(1);
119	        if (!digits.matches("\\d+")) {
120	            return telephone;
121	        }
122	        String countryCode = digits.substring(0, 1);
123	        String national = digits.substring(1);
124	        for (int codeLength = Math.min(3, digits.length() - 1); codeLength >= 1; codeLength--) {
125	            String candidate = digits.substring(0, codeLength);
126	            if (KNOWN_COUNTRY_CODES.contains(candidate)) {
127	                countryCode = candidate;
128	                national = digits.substring(codeLength);
129	                break;
130	            }
131	        }
132	        StringBuilder grouped = new StringBuilder();
133	        for (int i = 0; i < national.length(); i++) {
134	            if (i > 0 && i % 3 == 0) {
135	                grouped.append(' ');
136	            }
137	            grouped.append(national.charAt(i));
138	        }
139	        return "+" + countryCode + " " + grouped;
140	    }
141	
142	    /**
143	     * Compute the owner's check digit: a single Luhn check digit (0-9) over the digits contained in
144	     * the customerCode. Returns null when no customerCode has been assigned so owners without a code
145	     * serialize cleanly.
146	     */
147	    default Integer checkDigit(Owner owner) {
148	        String customerCode = owner.getCustomerCode();
149	        if (customerCode == null) {
150	            return null;
151	        }
152	        int sum = 0;
153	        boolean dbl = true;
154	        for (int i = customerCode.length() - 1; i >= 0; i--) {
155	            char c = customerCode.charAt(i);
156	            if (c < '0' || c > '9') {
157	                continue;
158	            }
159	            int d = c - '0';
160	            if (dbl) {
161	                d *= 2;
162	                if (d > 9) {
163	                    d -= 9;
164	                }
165	            }
166	            sum += d;
167	            dbl = !dbl;
168	        }
169	        return (10 - (sum % 10)) % 10;
170	    }
171	
172	    /**
173	     * Derive the owner's identity key, the single value into which all duplicate detection is
174	     * consolidated: {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Two
175	     * owners are duplicates only when their whole identity keys are equal. A null email or
176	     * householdId contributes an empty segment.
177	     */
178	    default String identityKey(Owner owner) {
179	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
180	        String email = owner.getEmail() == null ? "" : owner.getEmail();
181	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
182	        return telephone + "|" + email + "|" + householdId;
183	    }
184	
185	    /**
186	     * Determine the owner's preferred contact channel: 'EMAIL' when an email address is present,
187	     * otherwise 'PHONE'.
188	     */
189	    default String contactPreference(Owner owner) {
190	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
191	        return hasEmail ? "EMAIL" : "PHONE";
192	    }
193	
194	    /**
195	     * The calendar year in which the fiscal year containing {@code date} starts. The fiscal year
196	     * starts on 1 July, so dates in July through December map to their own calendar year while
197	     * dates in January through June map to the previous calendar year.
198	     */
199	    static int fiscalYearStart(java.time.LocalDate date) {
200	        return date.getMonthValue() >= java.time.Month.JULY.getValue()
201	            ? date.getYear() : date.getYear() - 1;
202	    }
203	
204	    /**
205	     * Derive the owner's fiscal year from the (business-day-adjusted) registrationDate, formatted
206	     * 'FY&lt;YY&gt;' where YY is the last two digits of the fiscal year's starting calendar year. The
207	     * fiscal year starts on 1 July. Returns null when no registrationDate is available so owners
208	     * without one serialize cleanly.
209	     */
210	    default String fiscalYear(Owner owner) {
211	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
212	        if (registrationDate == null) {
213	            return null;
214	        }
215	        return String.format("FY%02d", fiscalYearStart(registrationDate) % 100);
216	    }
217	
218	    /**
219	     * Build the owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is
220	     * the last two digits of the fiscal year (see {@link #fiscalYear(Owner)}) derived from the
221	     * business-day-adjusted registrationDate. Returns null when either source field is absent so
222	     * owners without an assigned code or registration date serialize cleanly.
223	     */
224	    default String membershipNumber(Owner owner) {
225	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
226	            return null;
227	        }
228	        return String.format("%s-M%02d", owner.getCustomerCode(),
229	            fiscalYearStart(owner.getRegistrationDate()) % 100);
230	    }
231	
232	    /**
233	     * Compute the owner's membership points. Starts at 0; add 2 when an email address is present;
234	     * add 1 when the owner has no namesakes (namesakeCount is 0); add 2 for a household of 3 or more
235	     * (householdSize); add 3 for tenure of at least one elapsed fiscal year, measured as the number
236	     * of fiscal-year starts (1 July) between the registrationDate and the current date. Because a
237	     * newly created owner has zero elapsed fiscal years, a new owner never earns the tenure points.
238	     */
239	    default Integer membershipPoints(Owner owner) {
240	        int points = 0;
241	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
242	        if (hasEmail) {
243	            points += 2;
244	        }
245	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
246	        if (noNamesakes) {
247	            points += 1;
248	        }
249	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
250	            points += 2;
251	        }
252	        if (owner.getRegistrationDate() != null
253	                && fiscalYearStart(java.time.LocalDate.now())
254	                    - fiscalYearStart(owner.getRegistrationDate()) >= 1) {
255	            points += 3;
256	        }
257	        return points;
258	    }
259	
260	    /**
261	     * Determine the owner's numeric membership level, derived from membershipPoints: 1 for 0-1
262	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points. The points-derived
263	     * level is then capped by {@code membershipLevelCap} when one was assigned at creation: a new
264	     * owner's level may not exceed one above the highest level among their existing household
265	     * members. When no cap was assigned (no existing household member), the points-derived level is
266	     * returned unchanged.
267	     */
268	    default Integer membershipLevel(Owner owner) {
269	        int points = membershipPoints(owner);
270	        int level;
271	        if (points <= 1) {
272	            level = 1;
273	        } else if (points <= 3) {
274	            level = 2;
275	        } else if (points <= 5) {
276	            level = 3;
277	        } else {
278	            level = 4;
279	        }
280	        Integer cap = owner.getMembershipLevelCap();
281	        if (cap != null && level > cap) {
282	            level = cap;
283	        }
284	        return level;
285	    }
286	
287	    /**
288	     * The fixed city-to-region table used to derive an owner's locality when the postcode is absent
289	     * or falls in no known range.
290	     */
291	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
292	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
293	
294	    /**
295	     * Region -&gt; inclusive 4-digit postcode range {low, high}: NSW 2000-2099, VIC 3000-3099,
296	     * QLD 4000-4099.
297	     */
298	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
299	        "NSW", new int[] {2000, 2099},
300	        "VIC", new int[] {3000, 3099},
301	        "QLD", new int[] {4000, 4099});
302	
303	    /**
304	     * Derive the owner's locality (canonical region), preferring the postcode: look up the region by
305	     * postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only fall back to the
306	     * city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is
307	     * absent or in no known range. Returns 'UNKNOWN' when neither source resolves a region.
308	     */
309	    default String locality(Owner owner) {
310	        String postcode = owner.getPostcode();
311	        if (postcode != null && postcode.matches("\\d{4}")) {
312	            int value = Integer.parseInt(postcode);
313	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
314	                int[] range = entry.getValue();
315	                if (value >= range[0] && value <= range[1]) {
316	                    return entry.getKey();
317	                }
318	            }
319	        }
320	        String city = owner.getCity();
321	        if (city == null) {
322	            return "UNKNOWN";
323	        }
324	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
325	    }
326	
327	    /**
328	     * The fixed region-to-timezone table used to derive an owner's timezone from its locality:
329	     * NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne, QLD-&gt;Australia/Brisbane.
330	     */
331	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
332	        "NSW", "Australia/Sydney",
333	        "VIC", "Australia/Melbourne",
334	        "QLD", "Australia/Brisbane");
335	
336	    /**
337	     * Derive the owner's timezone as an IANA name from its locality (canonical region) using the
338	     * fixed region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
339	     * QLD-&gt;Australia/Brisbane). Returns null when the locality is not in the table so owners with
340	     * an unknown region serialize cleanly.
341	     */
342	    default String timezone(Owner owner) {
343	        return REGION_TIMEZONE.get(locality(owner));
344	    }
345	
346	    Owner toOwner(OwnerDto ownerDto);
347	
348	    @Mapping(target = "id", ignore = true)
349	    @Mapping(target = "pets", ignore = true)
350	    Owner toOwner(OwnerFieldsDto ownerDto);
351	
352	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
353	
354	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
355	
356	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
357	        OwnerPageDto ownerPageDto = new OwnerPageDto();
358	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
359	        ownerPageDto.setPage(ownerPage.getNumber());
360	        ownerPageDto.setSize(ownerPage.getSize());
361	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
362	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
363	        return ownerPageDto;
364	    }
365	}
