69	 */
70	
71	@RestController
72	@CrossOrigin(exposedHeaders = "errors, content-type")
73	@RequestMapping("/api")
74	public class OwnerRestControllerV1 implements OwnersApi {
75	
76	    /** Dedicated audit logger; emits one line per successful owner create. */
77	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
78	
79	    private final ClinicService clinicService;
80	
81	    private final OwnerMapper ownerMapper;
82	
83	    private final PetMapper petMapper;
84	
85	    private final VisitMapper visitMapper;
86	
87	    /** HTTP header carrying the caller-supplied idempotency key for owner creates. */
88	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
89	
90	    /**
91	     * Records the owner created for each previously-seen idempotency key, so a create that repeats a
92	     * key returns the originally created owner instead of creating a duplicate. Keyed by the raw
93	     * header value; the stored value is the response returned for the first successful create.
94	     */
95	    private final Map<String, OwnerDto> idempotentCreations = new ConcurrentHashMap<>();
96	
97	    public OwnerRestControllerV1(ClinicService clinicService,
98	                                 OwnerMapper ownerMapper,
99	                                 PetMapper petMapper,
100	                                 VisitMapper visitMapper) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
110	        Collection<Owner> owners;
111	        if (lastName != null) {
112	            owners = this.clinicService.findOwnerByLastName(lastName);
113	        } else {
114	            owners = this.clinicService.findAllOwners();
115	        }
116	        if (owners.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
125	        Owner owner = this.clinicService.findOwnerById(ownerId);
126	        if (owner == null) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        // Idempotent create: when the request carries an 'Idempotency-Key' header that we have already
136	        // seen, return the owner originally created for that key with 200 instead of creating a
137	        // duplicate (which would otherwise be rejected as a 409 conflict). A brand-new key is recorded
138	        // below once the create succeeds; a request without the header is never treated as idempotent.
139	        String idempotencyKey = currentIdempotencyKey();
140	        if (idempotencyKey != null) {
141	            OwnerDto existing = idempotentCreations.get(idempotencyKey);
142	            if (existing != null) {
143	                return new ResponseEntity<>(existing, HttpStatus.OK);
144	            }
145	        }
146	        // Normalize the address up front so every downstream use (the required-field check,
147	        // household-duplicate detection, the shared household id and the stored/returned value)
148	        // works from the same canonical form. The structured 'addressLine1'/'addressLine2' fields are
149	        // preferred when present; the flat 'address' remains accepted for backward compatibility. Each
150	        // supplied line is normalized the same way, and the composed address is the normalized
151	        // addressLine1 with a single space and the normalized addressLine2 appended when present.
152	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
153	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
154	        boolean structuredAddress = !isBlank(normalizedAddressLine1);
155	        String normalizedAddress;
156	        if (structuredAddress) {
157	            normalizedAddress = normalizedAddressLine2.isEmpty()
158	                ? normalizedAddressLine1
159	                : normalizedAddressLine1 + " " + normalizedAddressLine2;
160	        } else {
161	            normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
162	        }
163	        List<String> missingFields = new ArrayList<>();
164	        if (isBlank(ownerFieldsDto.getFirstName())) {
165	            missingFields.add("firstName");
166	        }
167	        if (isBlank(ownerFieldsDto.getLastName())) {
168	            missingFields.add("lastName");
169	        }
170	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
171	        if (isBlank(normalizedAddress)) {
172	            missingFields.add("address");
173	        }
174	        if (isBlank(ownerFieldsDto.getCity())) {
175	            missingFields.add("city");
176	        }
177	        if (isBlank(ownerFieldsDto.getTelephone())) {
178	            missingFields.add("telephone");
179	        }
180	        if (!missingFields.isEmpty()) {
181	            throw new InvalidOwnerFieldsException(missingFields);
182	        }
183	        // A supplied registration date may not lie in the future: reject with 400 when the caller
184	        // provides a date later than the server's current date. Checked against the raw supplied value
185	        // (before any business-day adjustment) so a future date is never silently accepted.
186	        if (ownerFieldsDto.getRegistrationDate() != null
187	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
188	            throw new FutureRegistrationDateException(ownerFieldsDto.getRegistrationDate());
189	        }
190	        // Determine the effective registration date up front so every downstream use (the daily
191	        // create-limit, the stored value and anything derived from it such as the membership number's
192	        // year segment) works from the same business-day-adjusted date. The effective date is the
193	        // supplied value when present, otherwise the server's current date; a weekend date is rolled
194	        // forward to the following Monday.
195	        LocalDate effectiveRegistrationDate = ownerFieldsDto.getRegistrationDate() != null
196	            ? ownerFieldsDto.getRegistrationDate()
197	            : LocalDate.now();
198	        effectiveRegistrationDate = toBusinessDay(effectiveRegistrationDate);
199	        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
200	        // already carry this adjusted business day's registration date, no further owners may be
201	        // created for that day.
202	        int ownersRegisteredToday = countOwnersRegisteredOn(effectiveRegistrationDate);
203	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
204	            throw new DailyOwnerLimitExceededException(effectiveRegistrationDate);
205	        }
206	        // Flag a bulk signup once more than 80 owners have already been created for this
207	        // business day, sharing the same daily accumulation path as the create-limit rule above.
208	        boolean bulkSignupWarning = ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD;
209	        // Reject the request when the owner's city is already full: a city that already holds the
210	        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
211	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= MAX_OWNERS_PER_CITY) {
212	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
213	        }
214	        // Postcode is optional; when present it must be a 4-digit value that is valid for the
215	        // owner's city per the fixed region ranges. A malformed or out-of-range postcode is
216	        // rejected with a 400. An absent postcode leaves the request contract unchanged.
217	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
218	        // Normalize the telephone into E.164 form; a number that cannot form a valid
219	        // E.164 value is rejected with a 400.
220	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
221	        // Email is optional; when present it must be a syntactically valid address and is
222	        // stored lower-cased. An invalid address is rejected with a 400.
223	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
224	        // Derive the household id up front. It is a deterministic function of the normalized last name
225	        // and the postcode, so owners sharing a last name and postcode independently derive the same
226	        // value and are the same household. It is always computed (never null), regardless of whether
227	        // the caller opts into a shared household; 'sharesHousehold' now only bypasses the household
228	        // duplicate block below.
229	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
230	        String householdId = householdId(normalizedLastName, ownerFieldsDto.getPostcode());
231	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
232	        // All duplicate detection is consolidated into a single derived identity key:
233	        // 'normalizedTelephone + | + (email or empty) + | + householdId'. Because the telephone is
234	        // part of the key, two members of the same household (same householdId) with different
235	        // telephones have different keys and are both allowed; only an exact whole-key match is a
236	        // duplicate. Reject with 409 when a new owner's whole identity key equals an existing one's.
237	        String identityKey = identityKey(normalizedTelephone, normalizedEmail, householdId);
238	        boolean identityInUse = this.clinicService.findAllOwners().stream()
239	            .filter(existing -> !existing.isDeleted())
240	            .anyMatch(existing -> identityKey.equals(
241	                identityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
242	        if (identityInUse) {
243	            throw new DuplicateOwnerIdentityException(identityKey);
244	        }
245	        // Because the household is keyed on (last name, postcode), any existing owner carrying this
246	        // computed household id is already a member of this household. A second such owner is rejected
247	        // as a household duplicate (409) unless it is admitted as a distinct household member: either
248	        // the caller declares 'sharesHousehold', or the new owner supplies an email address. An email
249	        // uniquely identifies the owner (and, having cleared the identity check above, is known to be a
250	        // distinct identity), so it is treated as declaring a genuine additional member rather than an
251	        // accidental re-registration of the same person.
252	        boolean householdMemberExists = this.clinicService.findAllOwners().stream()
253	            .filter(existing -> !existing.isDeleted())
254	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
255	        boolean admittedAsHouseholdMember = sharesHousehold || normalizedEmail != null;
256	        if (householdMemberExists && !admittedAsHouseholdMember) {
257	            throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), normalizedAddress);
258	        }
259	        HttpHeaders headers = new HttpHeaders();
260	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
261	        // Store the composed, normalized address plus the normalized structured lines. The structured
262	        // lines are only retained when the owner was supplied in the structured form; a flat-address
263	        // owner keeps them null.
264	        owner.setAddress(normalizedAddress);
265	        owner.setAddressLine1(structuredAddress ? normalizedAddressLine1 : null);
266	        owner.setAddressLine2(structuredAddress && !normalizedAddressLine2.isEmpty()
267	            ? normalizedAddressLine2 : null);
268	        owner.setTelephone(normalizedTelephone);
269	        owner.setEmail(normalizedEmail);
270	        owner.setHouseholdId(householdId);
271	        // Record how many existing owners (before this create) share this owner's first and last
272	        // name, compared case-insensitively. Computed against the current owners so the new owner
273	        // itself is never counted.
274	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
275	        // Record the size of this owner's household (owners sharing the same householdId) after this
276	        // create: the existing members already stamped with the shared identifier plus this new
277	        // owner. An owner not admitted into any household is a household of one.
278	        owner.setHouseholdSize(countHouseholdMembers(householdId) + 1);
279	        // Cap the new owner's membership level at one above the current maximum membership level
280	        // among their existing household members (members already carrying this household id). The cap
281	        // applies to an owner joining an existing household on their own; an explicitly declared
282	        // 'sharesHousehold' member keeps its full points-based level. When there is no existing
283	        // household member, no cap applies and the level is left uncapped.
284	        owner.setMembershipLevelCap(sharesHousehold ? null : householdMembershipLevelCap(householdId));
285	        // Persist the bulk-signup flag computed above so it is returned on subsequent reads.
286	        owner.setBulkSignupWarning(bulkSignupWarning);
287	        // Store the business-day-adjusted effective registration date computed above. This defaults
288	        // to the server's current date when none was supplied and rolls any weekend date forward to
289	        // the following Monday, so everything derived from it (e.g. the membership number's year
290	        // segment) uses the adjusted date.
291	        owner.setRegistrationDate(effectiveRegistrationDate);
292	        // Assign the customer code: '<REGION>-<HASH8>' where REGION is the region derived from the
293	        // owner's postcode (falling back to the city-to-region table, else 'UNKNOWN', matching the
294	        // locality derivation) and HASH8 is the first 8 upper-case hex characters of
295	        // SHA-256(normalizedTelephone + lastName). Sequence numbers are no longer used.
296	        // Compute the base code, then de-duplicate it: if the computed value collides with an
297	        // existing owner's customerCode, append '-<n>' using the smallest n of 2 or more that
298	        // yields a value no existing owner already carries.
299	        owner.setCustomerCode(deduplicateCustomerCode(customerCode(
300	            deriveRegion(owner.getPostcode(), owner.getCity()), normalizedTelephone, owner.getLastName())));
301	        // Soft-match detection: an owner that cleared the hard-duplicate checks above may still
302	        // resemble an existing owner when it shares that owner's last name and postcode but carries a
303	        // different telephone. A declared household member ('sharesHousehold') is never a suspected
304	        // duplicate, so it is exempt; any other owner reaching here shares no household with an
305	        // existing owner (a household match without 'sharesHousehold' was already rejected above).
306	        // Flag a matched owner as a possible duplicate, recording its id; otherwise the flag is false
307	        // with no matched id.
308	        Owner possibleDuplicateOwner = sharesHousehold ? null : findPossibleDuplicate(
309	            owner.getLastName(), owner.getPostcode(), normalizedTelephone);
310	        owner.setPossibleDuplicate(possibleDuplicateOwner != null);
311	        owner.setPossibleDuplicateOf(possibleDuplicateOwner == null ? null : possibleDuplicateOwner.getId());
312	        this.clinicService.saveOwner(owner);
313	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
314	        // Emit an audit trail line for the successful create, carrying the owner id, the assigned
315	        // customer code, the effective registration date, the numeric membership level and the
316	        // assigned membership number.
317	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
318	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel(),
319	            ownerDto.getMembershipNumber());
320	        headers.setLocation(UriComponentsBuilder.newInstance()
321	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
322	        // Remember the created owner against its idempotency key (when one was supplied) so a later
323	        // create repeating the same key returns this same owner rather than creating a duplicate.
324	        if (idempotencyKey != null) {
