428	    /**
429	     * Read the {@code Idempotency-Key} header from the current request, or {@code null} when the
430	     * header is absent, blank, or no request is bound to the thread. The header is not part of the
431	     * generated API signature, so it is read from the ambient request rather than a method parameter.
432	     */
433	    private static String currentIdempotencyKey() {
434	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
435	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
436	            return null;
437	        }
438	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
439	        return isBlank(key) ? null : key;
