446	    /**
447	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
448	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
449	     * compared case-insensitively with collapsed whitespace.
450	     */
451	    private static String collapse(String value) {
452	        if (value == null) {
453	            return "";
454	        }
455	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
456	    }
457	
458	    /**
459	     * Common street-type abbreviations expanded during address normalization.
460	     */
461	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
462	        "ST", "STREET",
463	        "RD", "ROAD",
464	        "AVE", "AVENUE");
465	
466	    /**
467	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
468	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
469	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
470	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
471	     * address maps to itself.
472	     */
473	    private static String normalizeAddress(String value) {
474	        if (value == null) {
475	            return "";
476	        }
477	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
478	        if (collapsed.isEmpty()) {
479	            return "";
480	        }
481	        String[] tokens = collapsed.split(" ");
482	        StringBuilder sb = new StringBuilder(collapsed.length());
483	        for (int i = 0; i < tokens.length; i++) {
484	            if (i > 0) {
485	                sb.append(' ');
486	            }
487	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
488	        }
489	        return sb.toString();
490	    }
