492	    /**
493	     * Derive the stable household identifier shared by owners with the same normalized last name
494	     * and postcode. It is a deterministic function of those two values, so every member of a
495	     * household independently derives the same identifier: the first 12 upper-case hex characters
496	     * of {@code SHA-256(normalizedLastName + '|' + postcode)}. A {@code null} postcode contributes
497	     * an empty segment.
498	     */
499	    private static String householdId(String normalizedLastName, String postcode) {
500	        try {
501	            byte[] digest = MessageDigest.getInstance("SHA-256")
502	                .digest((normalizedLastName + "|" + (postcode == null ? "" : postcode))
503	                    .getBytes(StandardCharsets.UTF_8));
504	            StringBuilder sb = new StringBuilder(digest.length * 2);
505	            for (byte b : digest) {
506	                sb.append(String.format("%02x", b));
507	            }
508	            return sb.substring(0, 12).toUpperCase();
509	        }
510	        catch (NoSuchAlgorithmException e) {
511	            throw new IllegalStateException("SHA-256 not available", e);
512	        }
513	    }
