515	    /**
516	     * Derive the identity key into which all duplicate detection is consolidated:
517	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A null email or
518	     * household id contributes an empty segment. Two owners are duplicates only when their whole
519	     * identity keys are equal.
520	     */
521	    private static String identityKey(String telephone, String email, String householdId) {
522	        return (telephone == null ? "" : telephone)
523	            + "|" + (email == null ? "" : email)
524	            + "|" + (householdId == null ? "" : householdId);
525	    }
