527	    /**
528	     * Count the existing owners that share the given first and last name, compared
529	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
530	     * namesakes that already existed at creation time (the new owner itself is not included).
531	     */
532	    private int countNamesakes(String firstName, String lastName) {
533	        return (int) this.clinicService.findAllOwners().stream()
534	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
535	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
536	                && existing.getLastName().equalsIgnoreCase(lastName))
537	            .count();
