540	    /**
541	     * Count the existing owners that already belong to the given household (i.e. carry the same
542	     * non-null householdId). Called after any existing members have been backfilled with the shared
543	     * identifier but before the new owner is saved, so the returned value reflects the members that
544	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
545	     * new owner is not part of any household ({@code householdId} is null).
546	     */
547	    private int countHouseholdMembers(String householdId) {
548	        if (householdId == null) {
549	            return 0;
550	        }
551	        return (int) this.clinicService.findAllOwners().stream()
552	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
553	            .count();
554	    }
