556	    /**
557	     * Compute the membership-level cap for a new owner joining the given household: one above the
558	     * current maximum membership level among the existing (non-deleted) members already carrying
559	     * this household id, using each member's effective (already-capped) level as returned to
560	     * clients. Returns {@code null} when the household has no existing member, so no cap applies.
561	     */
562	    private Integer householdMembershipLevelCap(String householdId) {
563	        if (householdId == null) {
564	            return null;
565	        }
566	        java.util.OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
567	            .filter(existing -> !existing.isDeleted())
568	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
569	            .mapToInt(existing -> ownerMapper.membershipLevel(existing))
570	            .max();
571	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
572	    }
