574	    /**
575	     * Find an existing owner that this new owner is a possible (soft) duplicate of: one that shares
576	     * the new owner's last name (compared case-insensitively) and postcode while carrying a different
577	     * (already normalized) telephone. When several existing owners match, the earliest (lowest id) is
578	     * returned so the result is deterministic. Returns {@code null} when there is no such owner —
579	     * including when the new owner has no last name or postcode, since a shared postcode is required
580	     * to match.
581	     */
582	    private Owner findPossibleDuplicate(String lastName, String postcode, String normalizedTelephone) {
583	        if (isBlank(lastName) || isBlank(postcode)) {
584	            return null;
585	        }
586	        return this.clinicService.findAllOwners().stream()
587	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
588	            .filter(existing -> postcode.equals(existing.getPostcode()))
589	            .filter(existing -> !normalizedTelephone.equals(existing.getTelephone()))
590	            .min(java.util.Comparator.comparing(Owner::getId))
591	            .orElse(null);
592	    }
