641	    /**
642	     * Roll a date forward onto a business day: Saturdays, Sundays and listed public holidays are
643	     * advanced one day at a time until a non-weekend, non-holiday day is reached, while an ordinary
644	     * business day is returned unchanged. Used so the effective registration date (whether supplied
645	     * or defaulted) always falls on a business day.
646	     */
647	    private static LocalDate toBusinessDay(LocalDate date) {
648	        while (isWeekendOrHoliday(date)) {
649	            date = date.plusDays(1);
650	        }
651	        return date;
652	    }
653	
654	    private static boolean isWeekendOrHoliday(LocalDate date) {
655	        return switch (date.getDayOfWeek()) {
656	            case SATURDAY, SUNDAY -> true;
657	            default -> PUBLIC_HOLIDAYS.contains(date);
658	        };
659	    }
