661	    /**
662	     * Build the customer code for a new owner: {@code '<REGION>-<HASH8>'} where REGION is the region
663	     * derived from the owner's postcode/city and HASH8 is the first 8 upper-case hex characters of
664	     * {@code SHA-256(normalizedTelephone + lastName)} (e.g. {@code 'NSW-1A2B3C4D'}).
665	     */
666	    private static String customerCode(String region, String normalizedTelephone, String lastName) {
667	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
668	    }
669	
670	    /**
671	     * Ensure the computed customer code is unique across existing owners. When {@code base} is
672	     * already free it is returned unchanged; otherwise {@code '-<n>'} is appended using the smallest
673	     * {@code n} of 2 or more that produces a value no existing owner already carries.
674	     */
675	    private String deduplicateCustomerCode(String base) {
676	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
677	            .map(Owner::getCustomerCode)
678	            .filter(java.util.Objects::nonNull)
679	            .collect(java.util.stream.Collectors.toSet());
680	        if (!inUse.contains(base)) {
681	            return base;
682	        }
683	        int n = 2;
684	        while (inUse.contains(base + "-" + n)) {
685	            n++;
686	        }
687	        return base + "-" + n;
688	    }
689	
690	    /**
691	     * First 8 upper-case hex characters of {@code SHA-256(input)}.
692	     */
693	    private static String hash8(String input) {
694	        try {
695	            byte[] digest = MessageDigest.getInstance("SHA-256")
696	                .digest(input.getBytes(StandardCharsets.UTF_8));
697	            StringBuilder sb = new StringBuilder(digest.length * 2);
698	            for (byte b : digest) {
699	                sb.append(String.format("%02x", b));
700	            }
701	            return sb.substring(0, 8).toUpperCase();
702	        }
703	        catch (NoSuchAlgorithmException e) {
704	            throw new IllegalStateException("SHA-256 not available", e);
705	        }
706	    }
707	
708	    /**
709	     * Derive the owner's region, preferring the postcode: look up the region by postcode range first
710	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), then fall back to the city-to-region table
711	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is absent or in no known
712	     * range. Returns {@code 'UNKNOWN'} when neither source resolves a region. This mirrors the
713	     * mapper's locality derivation, so the customer code's region segment and the owner's locality
714	     * always agree.
715	     */
716	    private static String deriveRegion(String postcode, String city) {
717	        if (postcode != null && postcode.matches("\\d{4}")) {
718	            int value = Integer.parseInt(postcode);
719	            for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
720	                int[] range = entry.getValue();
721	                if (value >= range[0] && value <= range[1]) {
722	                    return entry.getKey();
723	                }
724	            }
725	        }
726	        if (city == null) {
727	            return "UNKNOWN";
728	        }
729	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
730	    }
731	
732	    /**
733	     * The fixed city-to-region table used to validate a supplied postcode against the owner's city
734	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). A city not present here has no known region
735	     * and accepts any 4-digit postcode.
736	     */
737	    private static final Map<String, String> CITY_REGION = Map.of(
738	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
739	
740	    /**
741	     * The fixed region-to-postcode ranges (inclusive): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
742	     * Each entry is a two-element {@code {low, high}} array.
743	     */
744	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
745	        "NSW", new int[] {2000, 2099},
746	        "VIC", new int[] {3000, 3099},
747	        "QLD", new int[] {4000, 4099});
748	
749	    /**
750	     * Validate an optional owner postcode. Does nothing when no postcode was supplied (the field is
751	     * optional and the request contract stays backward-compatible). When supplied it must be exactly
752	     * 4 digits and, if the city maps to a known region, must fall within that region's inclusive
753	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
754	     * 4-digit postcode. A malformed or out-of-range postcode throws an
755	     * {@link InvalidOwnerFieldsException} so the request is rejected with a 400.
756	     */
757	    private static void validatePostcode(String city, String postcode) {
758	        if (postcode == null || postcode.isEmpty()) {
759	            return;
760	        }
761	        if (!postcode.matches("\\d{4}")) {
762	            throw new InvalidOwnerFieldsException(List.of("postcode"));
763	        }
764	        String region = city == null ? null : CITY_REGION.get(city);
765	        if (region == null) {
766	            return;
767	        }
768	        int[] range = REGION_POSTCODES.get(region);
769	        int value = Integer.parseInt(postcode);
770	        if (value < range[0] || value > range[1]) {
771	            throw new InvalidOwnerFieldsException(List.of("postcode"));
772	        }
773	    }
774	
775	    /**
776	     * Required national-number length for each E.164 country calling code we validate: a
777	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
778	     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
779	     */
780	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
781	        "1", 10,
782	        "61", 9);
783	
784	    /**
785	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
786	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
787	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
788	     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
789	     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
790	     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
791	     * rejected with a 400.
792	     */
793	    private static String toE164(String raw) {
794	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
795	        boolean hasCountryCode = cleaned.startsWith("+");
796	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
797	        if (!digits.matches("\\d+")) {
798	            throw new InvalidOwnerFieldsException(List.of("telephone"));
799	        }
800	        if (!hasCountryCode) {
801	            if (digits.startsWith("0")) {
802	                digits = digits.substring(1);
803	            }
804	            digits = "61" + digits;
805	        }
806	        if (digits.length() < 8 || digits.length() > 15) {
807	            throw new InvalidOwnerFieldsException(List.of("telephone"));
808	        }
809	        // For a recognised country code, the national number (the digits after the code) must be
810	        // exactly the expected length for that country. Match the longest known code so a shorter
811	        // code that is a prefix of another cannot mask it.
812	        for (int codeLength = 3; codeLength >= 1; codeLength--) {
813	            if (digits.length() <= codeLength) {
814	                continue;
815	            }
816	            String countryCode = digits.substring(0, codeLength);
817	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
818	            if (requiredNationalLength != null) {
819	                if (digits.length() - codeLength != requiredNationalLength) {
820	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
821	                }
822	                break;
823	            }
824	        }
825	        return "+" + digits;
826	    }
