828	    /**
829	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
830	     * and a domain with at least one dot-separated label, none of which contain whitespace or
831	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
832	     */
833	    private static final Pattern EMAIL_PATTERN =
834	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
835	
836	    /**
837	     * Disposable email domains that are not accepted for an owner. An email whose domain (the part
838	     * after the {@code @}, compared case-insensitively) is on this blocklist is rejected with a 400.
839	     */
840	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
841	        "mailinator.com", "tempmail.com", "guerrillamail.com");
842	
843	    /**
844	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
845	     * supplied (the field is optional). When supplied it must be a syntactically valid address whose
846	     * domain is not on the disposable-domain blocklist, otherwise an
847	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400. A valid
848	     * address is returned lower-cased.
849	     */
850	    private static String normalizeEmail(String email) {
851	        if (email == null || email.isEmpty()) {
852	            return null;
853	        }
854	        String trimmed = email.trim();
855	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
856	            throw new InvalidOwnerFieldsException(List.of("email"));
857	        }
858	        String normalized = trimmed.toLowerCase();
859	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
860	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
861	            throw new InvalidOwnerFieldsException(List.of("email"));
862	        }
863	        return normalized;
864	    }
865	}
