/**
 * Derive the identity key into which all duplicate detection is consolidated: the full lower-case
 * hex SHA-256 over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. A
 * null email or last name contributes an empty segment. Two owners are duplicates only when their
 * whole identity keys are equal.
 */
private static String identityKey(String telephone, String email, String lastName) {
    String raw = (telephone == null ? "" : telephone)
        + "|" + (email == null ? "" : email.toLowerCase())
        + "|" + soundex(lastName);
    try {
        byte[] digest = MessageDigest.getInstance("SHA-256")
            .digest(raw.getBytes(StandardCharsets.UTF_8));
        StringBuilder sb = new StringBuilder(digest.length * 2);
        for (byte b : digest) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
    catch (NoSuchAlgorithmException e) {
        throw new IllegalStateException("SHA-256 not available", e);
    }
}

/**
 * American Soundex code of {@code value}: the retained first letter followed by up to three
 * digits, zero-padded to length four. Adjacent letters with the same code (and letters separated
 * only by h or w) collapse to one digit, while a vowel between them keeps both. Returns an empty
 * string when {@code value} contains no letters. Mirrors {@link OwnerMapper#soundex(String)} so
 * the identity key computed here matches the one the mapper exposes on the owner.
 */
private static String soundex(String value) {
    if (value == null) {
        return "";
    }
    StringBuilder letters = new StringBuilder();
    for (char c : value.toUpperCase().toCharArray()) {
        if (c >= 'A' && c <= 'Z') {
            letters.append(c);
        }
    }
    if (letters.length() == 0) {
        return "";
    }
    StringBuilder code = new StringBuilder();
    code.append(letters.charAt(0));
    char prev = soundexDigit(letters.charAt(0));
    for (int i = 1; i < letters.length() && code.length() < 4; i++) {
        char c = letters.charAt(i);
        if (c == 'H' || c == 'W') {
            continue;
        }
        char digit = soundexDigit(c);
        if (digit != '0' && digit != prev) {
            code.append(digit);
        }
        prev = (c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U' || c == 'Y') ? '0' : digit;
    }
    while (code.length() < 4) {
        code.append('0');
    }
    return code.substring(0, 4);
}

/**
 * Map a single upper-case letter to its Soundex digit, or {@code '0'} for letters that are not
 * coded (a, e, i, o, u, y, h, w).
 */
private static char soundexDigit(char c) {
    return switch (c) {
        case 'B', 'F', 'P', 'V' -> '1';
        case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
        case 'D', 'T' -> '3';
        case 'L' -> '4';
        case 'M', 'N' -> '5';
        case 'R' -> '6';
        default -> '0';
    };
}

